const OUT_DIR = path.join(WORKSPACE, '.reflexion-out');

async function main() {
  if (!EVENT_PATH || !fs.existsSync(EVENT_PATH)) {
    console.error('GITHUB_EVENT_PATH is not set or file does not exist.');
    process.exit(1);
  }

  const eventPayload = JSON.parse(fs.readFileSync(EVENT_PATH, 'utf-8'));

  try {
    if (process.env.GITHUB_EVENT_NAME === 'workflow_dispatch') {
      await handleDispatchPath(eventPayload);
    } else if (process.env.GITHUB_EVENT_NAME === 'issue_comment') {
      await handleResumePath(eventPayload);
    } else if (process.env.GITHUB_EVENT_NAME === 'issues') {
      await handleStartPath(eventPayload);
    } else {
      console.log('Unhandled event type:', process.env.GITHUB_EVENT_NAME);
    }
  } catch (err) {
    console.error('Runner error:', err);
    await postDiagnosticComment(eventPayload, err.message);
    process.exit(1);
  }
}

async function handleDispatchPath(payload) {
  const issueNumber = payload.inputs?.issue_number;
  if (!issueNumber) {
    console.error('No issue number provided in dispatch inputs.');
    process.exit(0);
  }

  // Fetch issue details using the REST API to act like a normal labeled event
  const repo = process.env.GITHUB_REPOSITORY;
  const url = `https://api.github.com/repos/${repo}/issues/${issueNumber}`;
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (!res.ok) {
    throw new Error(`Failed to fetch issue data: ${res.statusText}`);
  }

  const issue = await res.json();
  await handleStartPath({ issue });
}

async function handleStartPath(payload) {
  const issue = payload.issue;
  if (!issue) {
    console.error('No issue found in payload.');
    process.exit(0);
  }

  console.log(`Starting loop for issue #${issue.number}`);

  const maxRevisions = process.env.REFLEXION_MAX_REVISIONS || '3';
  const maxCostUsd = process.env.REFLEXION_MAX_COST_USD || '3';

  const turnCount = await countTurns(issue.number);
  if (turnCount >= 10) {
    throw new Error('Hard stop: Maximum of 10 loop turns per issue reached.');
  }

  const brief = `${issue.title}\n\n${issue.body || ''}`;

  const briefFile = path.join(WORKSPACE, 'reflexion-brief.md');
  fs.writeFileSync(briefFile, brief, 'utf-8');

  console.log('Invoking reflexion-loop.ts for start...');
  const cmd = 'npx';
  const args = [
    'tsx',
    'scripts/reflexion-loop.ts',
    '--brief-file',
    briefFile,
    '--repo',
    WORKSPACE,
    '--max',
    maxRevisions,
    '--out',
    OUT_DIR,
  ];

  const result = spawnSync(cmd, args, {
    stdio: 'inherit',
    env: { ...process.env, REFLEXION_MAX_COST_USD: maxCostUsd },
  });

  if (result.status !== 0 && result.status !== 2) {
    throw new Error(`Reflexion script failed with status ${result.status}`);
  }

  await postResultComment(issue.number, null);
}

async function countTurns(issueNumber) {
  const repo = process.env.GITHUB_REPOSITORY;
  const listCommentsUrl = `https://api.github.com/repos/${repo}/issues/${issueNumber}/comments?per_page=100`;

  const res = await fetch(listCommentsUrl, {
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });
  if (!res.ok) return 0;

  const comments = await res.json();
  let count = 0;
  for (const c of comments) {
    if (
      c.user.login === 'github-actions[bot]' &&
      c.body.includes('<!-- reflexion-run:')
    ) {

      count++;
    }
  }
  return count;
}

async function downloadArtifact(runId, artifactName, token) {
  console.log(`Downloading artifact ${artifactName} from run ${runId}`);

  const repo = process.env.GITHUB_REPOSITORY;
  const listUrl = `https://api.github.com/repos/${repo}/actions/runs/${runId}/artifacts`;

  const res = await fetch(listUrl, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (!res.ok) {
    throw new Error(`Failed to list artifacts: ${res.statusText}`);
  }

  const data = await res.json();
  const artifact = data.artifacts.find((a) => a.name === artifactName);

  if (!artifact) {
    throw new Error(`Artifact ${artifactName} not found for run ${runId}`);
  }

  const downloadUrl = artifact.archive_download_url;
  const downloadRes = await fetch(downloadUrl, {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });

  if (!downloadRes.ok) {
    throw new Error(`Failed to download artifact: ${downloadRes.statusText}`);
  }

  const arrayBuffer = await downloadRes.arrayBuffer();
  const zipFile = path.join(WORKSPACE, 'artifact.zip');
  fs.writeFileSync(zipFile, Buffer.from(arrayBuffer));

  const AdmZip = require('adm-zip');
  const zip = new AdmZip(zipFile);

  fs.mkdirSync(OUT_DIR, { recursive: true });
  zip.extractAllTo(OUT_DIR, true);

  console.log(`Artifact extracted to ${OUT_DIR}`);
}

async function verifyArtifactExists(runId, artifactName, token) {
  try {
    const repo = process.env.GITHUB_REPOSITORY;
    const listUrl = `https://api.github.com/repos/${repo}/actions/runs/${runId}/artifacts`;

    const res = await fetch(listUrl, {

      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });

    if (!res.ok) {
      console.error(
        `Failed to list artifacts for run ${runId}: ${res.statusText}`
      );
      return false;
    }

    const data = await res.json();
    if (!data.artifacts) return false;

    const artifact = data.artifacts.find((a) => a.name === artifactName);
    return !!artifact;
  } catch (err) {
    console.error(`Error verifying artifact for run ${runId}:`, err);
    return false;
  }
}

async function handleResumePath(payload) {
  const comment = payload.comment;
  const issue = payload.issue;

  if (!comment || !issue) return;

  if (comment.user.login === 'github-actions[bot]') {
    console.log('Ignoring comment from github-actions[bot]');
    return;
  }

  if (!comment.body.startsWith('/reflexion')) {
    console.log('Not a reflexion command comment.');
    return;
  }

  console.log(`Resuming loop for issue #${issue.number}`);

  const repo = process.env.GITHUB_REPOSITORY;
  const listCommentsUrl = `https://api.github.com/repos/${repo}/issues/${issue.number}/comments?per_page=100`;

  const res = await fetch(listCommentsUrl, {
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (!res.ok) {
    throw new Error(`Failed to list comments: ${res.statusText}`);
  }

  const comments = await res.json();

  // Idempotency check: has the bot already replied to THIS comment ID?
  for (let i = comments.length - 1; i >= 0; i--) {

  const c = comments[i];
  if (c.user.login === 'github-actions[bot]') {
    const processedId = extractProcessedCommentIdMarker(c.body);
    if (processedId === String(comment.id)) {
      console.log(
        `Comment ID ${comment.id} has already been processed by the bot. Idempotency safeguard applied.`
      );
      process.exit(0);
    }
  }
}

const turnCount = await countTurns(issue.number);
if (turnCount >= 10) {
  throw new Error('Hard stop: Maximum of 10 loop turns per issue reached.');
}

let prevRunId = null;
const artifactName = `reflexion-state-${issue.number}`;

for (let i = comments.length - 1; i >= 0; i--) {
  const c = comments[i];
  if (c.user.login === 'github-actions[bot]') {
    const runId = extractRunIdMarker(c.body);
    if (runId) {
      console.log(
        `Checking if artifact exists for candidate runId: ${runId}`
      );
      const exists = await verifyArtifactExists(runId, artifactName, TOKEN);
      if (exists) {
        prevRunId = runId;
        break;
      } else {
        console.log(
          `Artifact not found or expired for runId: ${runId}. Skipping.`
        );
      }
    }
  }
}

if (!prevRunId) {
  const msg = `### 🚨 Prior State Not Found\n\nThe prior reflexion state could not be found. The artifact may have expired after the 7-day retention period, or the previous runs failed to produce a valid state.\n\nPlease start a fresh run by closing/reopening the issue, or triggering a new run manually.`;
  await createIssueComment(issue.number, msg);
  process.exit(1);
}

// Download the artifact first, because we want to extract the state/questions
// and we also need it for resume if the comment is valid.
try {
  await downloadArtifact(prevRunId, artifactName, TOKEN);
} catch (err) {
  const msg = `### 🚨 Failed to Download Prior State\n\nFailed to download prior state artifact for run ID \`${prevRunId}\`: ${err.message}\n\nPlease try starting a fresh run by closing and reopening this issue.`;
  await createIssueComment(issue.number, msg);
  process.exit(1);
}

// Parse and validate the comment body
let yamlBlock = null;
let parsedYaml = null;

let parseErrorMsg = null;

try {
  yamlBlock = extractYamlBlock(comment.body);
  if (!yamlBlock) {
    throw new Error(
      'No YAML block found in your comment. Please ensure your response contains a code block with answers starting with \`\`\`yaml answers:\`\`.'
    );
  }

  try {
    parsedYaml = yaml.load(yamlBlock);
  } catch (e) {
    throw new Error(
      `Failed to parse the YAML block. Please ensure it has valid YAML syntax. Details: ${e.message}`
    );
  }

  const validation = validateAnswers(parsedYaml);
  if (!validation.success) {
    const errors = validation.error.errors
      .map((err) => `- \`${err.path.join('.')}\`: ${err.message}`)
      .join('\n');
    throw new Error(`YAML block schema validation failed:\n${errors}`);
  }
} catch (err) {
  parseErrorMsg = err.message;
}

if (parseErrorMsg) {
  // We had an answer-parsing/validation failure!
  // Post a helpful comment with a copy-paste-ready answers template.
  let answersTemplate = null;
  try {
    const stateFiles = fs
      .readdirSync(OUT_DIR)
      .filter(
        (f) =>
          f.endsWith('.json') &&
          !f.endsWith('-answers.json') &&
          !f.endsWith('-critique.json') &&
          f !== 'eval.json'
      );
    if (stateFiles.length > 0) {
      const statePath = path.join(OUT_DIR, stateFiles[0]);
      const state = JSON.parse(fs.readFileSync(statePath, 'utf-8'));
      if (state.interview && state.interview.questions) {
        answersTemplate = `\`\`\`yaml answers:\nrunId: "${prevRunId}"\n# directive: "approve"\ndecisions:\n`;
        state.interview.questions.forEach((q) => {
          answersTemplate += `  - id: "${q.id}"\n    answer: ""\n`;
        });
        answersTemplate += '```';
      }
    }
  } catch (e) {
    console.warn(
      'Failed to read state file for error template generation:',
      e
    );
  }

    if (!answersTemplate) {
      answersTemplate = `\`\`\`yaml answers:\nrunId: "${prevRunId}"\n# directive: "approve"\ndecisions:\n  - id: "question_id_here"\n    answer: ""\n\`\`\``;
    }

    const msg = `### 🚨 Malformed answers submission\n\nThere was an issue processing your response:\n\n${parseErrorMsg}\n\n#### Please reply again using this copy-paste-ready template:\n\n${answersTemplate}`;
    await createIssueComment(issue.number, msg);
    process.exit(1);
  }

  const answersFile = path.join(WORKSPACE, 'reflexion-answers.yaml');
  fs.writeFileSync(
    answersFile,
    `\`\`\`yaml answers:\n${yamlBlock}\n\`\`\``,
    'utf-8'
  );

  console.log('Invoking reflexion-loop.ts for resume...');
  const maxCostUsd = process.env.REFLEXION_MAX_COST_USD || '3';
  const cmd = 'npx';
  const args = [
    'tsx',
    'scripts/reflexion-loop.ts',
    '--resume',
    OUT_DIR,
    '--answers',
    answersFile,
  ];

  const result = spawnSync(cmd, args, {
    stdio: 'inherit',
    env: { ...process.env, REFLEXION_MAX_COST_USD: maxCostUsd },
  });

  if (result.status !== 0 && result.status !== 2) {
    throw new Error(`Reflexion script failed with status ${result.status}`);
  }

  await postResultComment(issue.number, comment.id);
}

async function postResultComment(issueNumber, triggeringCommentId) {
  const stateFiles = fs
    .readdirSync(OUT_DIR)
    .filter(
      (f) =>
        f.endsWith('.json') &&
        !f.endsWith('-answers.json') &&
        !f.endsWith('-critique.json') &&
        f !== 'eval.json'
    );
  if (stateFiles.length === 0) {
    throw new Error('No state file generated.');
  }

  const statePath = path.join(OUT_DIR, stateFiles[0]);
  const state = JSON.parse(fs.readFileSync(statePath, 'utf-8'));

  let scoreTable = '| Rev | Score |\n|---|---|\n';
  if (state.critiques) {

  state.critiques.forEach((c, idx) => {
    scoreTable += `| ${idx + 1} | ${c.score}/10 |\n`;
  });
}

let verdict = 'stop';
if (state.stopReason === 'passed') verdict = 'approve';
else if (
  state.stopReason === 'max-revisions' ||
  state.stopReason === 'budget-exceeded'
)
  verdict = state.stopReason;
else if (state.interview) verdict = state.interview.recommendation;

let interviewQuestions = null;
let answersTemplate = null;

if (state.interview && state.interview.questions) {
  interviewQuestions = state.interview.questions
    .map((q) => `**${q.id}**: ${q.question}\n*Why: ${q.why}*`)
    .join('\n\n');
  answersTemplate = `\`\`\`yaml answers:\nrunId: "${RUN_ID}"\n# directive: "approve"\ndecisions:\n`;
  state.interview.questions.forEach((q) => {
    answersTemplate += `  - id: "${q.id}"\n    answer: ""\n`;
  });
  answersTemplate += '```';
}

let usageCost = `Total tokens: ${state.usage?.totalTokens || 0} (Cost: $${state.usage?.costUsd || 0})`;

let idePrompt = null;
if (verdict === 'approve') {
  const promptPath = path.join(OUT_DIR, 'ide-prompt.md');
  if (fs.existsSync(promptPath)) {
    idePrompt = fs.readFileSync(promptPath, 'utf-8');
  }
}

let plan = null;
const planPath = path.join(OUT_DIR, 'plan.md');
if (fs.existsSync(planPath)) {
  plan = fs.readFileSync(planPath, 'utf-8');
}

let commentBody = formatRunnerComment({
  runId: RUN_ID,
  triggeringCommentId: triggeringCommentId,
  scoreTable,
  adjudicatorVerdict: verdict,
  interviewQuestions,
  answersTemplate,
  usageCost,
  idePrompt,
  plan,
});

if (state.criticDegraded) {
  commentBody =
    'WARNING: Critique ran in fallback mode (Gemini 3.1 Pro) because the Claude API was unavailable — model separation was reduced; review this plan with extra scrutiny.\n\n' +
    commentBody;

  }

  await createIssueComment(issueNumber, commentBody);

  if (verdict === 'approve') {
    await applyApprovedLabel(issueNumber);
  }
}

async function postDiagnosticComment(payload, errorMsg) {
  const issueNumber = payload.issue?.number || payload.inputs?.issue_number;
  if (!issueNumber) return;

  const triggeringCommentId = payload.comment?.id;

  const commentBody = formatRunnerComment({
    runId: RUN_ID,
    triggeringCommentId,
    diagnostic: errorMsg,
  });

  await createIssueComment(issueNumber, commentBody);
}

async function createIssueComment(issueNumber, body) {
  const repo = process.env.GITHUB_REPOSITORY;
  const url = `https://api.github.com/repos/${repo}/issues/${issueNumber}/comments`;

  const res = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ body }),
  });

  if (!res.ok) {
    console.error(`Failed to post comment: ${res.statusText}`);
  }
}

async function applyApprovedLabel(issueNumber) {
  const repo = process.env.GITHUB_REPOSITORY;
  const url = `https://api.github.com/repos/${repo}/issues/${issueNumber}/labels`;

  const res = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ labels: ['reflexion:approved'] }),
  });

  if (!res.ok) {
    console.error(`Failed to apply label: ${res.statusText}`);
  }

}

main().catch((err) => {
  console.error('Fatal error in runner:', err);
  process.exit(1);
});

export function parseYamlAnswers(text: string): Answers {
  // If it's a markdown file with a fenced block, extract the block
  const match = text.match(/```yaml answers:\s*([\s\S]*?)```/);
  const yamlContent = match ? match[1] : text;

  const lines = yamlContent.split('\n');
  const result: any = { decisions: [] };
  let inDecisions = false;
  let currentDecision: any = null;

  for (let line of lines) {
    line = line.replace(/#.*$/, ''); // strip comments
    if (!line.trim()) continue;

    const runIdMatch = line.match(/^runId:\s*"?([^"]+)"?$/);
    if (runIdMatch) {
      result.runId = runIdMatch[1].trim();
      continue;
    }

    const directiveMatch = line.match(/^directive:\s*"?([^"]+)"?$/);
    if (directiveMatch) {
      result.directive = directiveMatch[1].trim();
      continue;
    }

    if (line.match(/^decisions:/)) {
      inDecisions = true;
      continue;
    }

    if (inDecisions) {
      const idMatch = line.match(/^\s*-\s*id:\s*"?([^"]+)"?$/);
      if (idMatch) {
        if (currentDecision) result.decisions.push(currentDecision);
        currentDecision = { id: idMatch[1].trim() };
        continue;
      }
      const answerMatch = line.match(/^\s*answer:\s*"?([^"]*)"?$/);
      if (answerMatch && currentDecision) {
        currentDecision.answer = answerMatch[1].trim();
      }
    }
  }
  if (currentDecision) result.decisions.push(currentDecision);

  return result as Answers;
}

export function formatInterviewMd(runId: string, questions: any[]): string {
  const md = [
    '# Reflexion Loop Interview',
    '',
    'The Adjudicator requires human input to proceed.',
    '',
    '## Questions',
  ];

  for (const q of questions) {
    md.push(`**${q.id}** [${q.target} \`${q.ref}\`]: ${q.question}`);
    md.push(`*Why: ${q.why}*`);
    md.push('');
  }

  md.push('## Answers');
  md.push(
    'Fill in the `answer` fields below, or set `directive` to `approve` or `stop`.'
  );
  md.push('```yaml answers:');
  md.push(`runId: "${runId}"`);
  md.push('# directive: "approve"');
  md.push('decisions:');

  for (const q of questions) {
    md.push(`  - id: "${q.id}"`);
    md.push(`    answer: ""`);
  }

  md.push('```');

  return md.join('\n');
}

#!/usr/bin/env tsx
/**
 * Reflexion Loop CLI — the cross-repo entry point.
 *
 *   rtk run reflexion-loop -- "Add token-bucket rate limiting to the public API"
 *   npx tsx scripts/reflexion-loop.ts --brief-file ticket.md --repo . --max 3
 *
 * Generator = Gemini, Critic + Adjudicator = Claude (keys from the environment:
 * GEMINI_API_KEY + ANTHROPIC_API_KEY). Writes plan.md, critique.json and a
 * dependency-free SVG diminishing-returns chart. Exit code 0 = passed,
 * 2 = hit the revision cap without passing (handy in CI).
 *
 * Relative imports (matching scripts/migrate-analytics.ts) so it runs under tsx
 * without the '@/' path alias.
 */
import * as fs from 'fs';
import * as path from 'path';

import {
  resumeReflexion,
  runReflexion,
  type ReflexionResult,
} from '../src/lib/ai/reflexion/engine';
import { runnerFromEnv } from '../src/lib/ai/reflexion/providers-env';
import { Answers, ReflexionStateV2 } from '../src/lib/ai/reflexion/schema';
import { FileStateStore } from '../src/lib/ai/reflexion/state-store';
import { assessTask, enforceTier, type Tier } from '../src/lib/ai/tier-policy';
import { langfuseSink } from '../src/lib/langfuse-sink';
import { formatInterviewMd, parseYamlAnswers } from './reflexion-loop-utils';

function arg(flag: string): string | undefined {
  const i = process.argv.indexOf(flag);
  return i >= 0 ? process.argv[i + 1] : undefined;
}

function hasFlag(flag: string): boolean {
  return process.argv.includes(flag);
}

function readStack(repo: string, maxCharsPerFile = 1800): string {
  const chunks: string[] = [];
  for (const f of STACK_FILES) {
    const p = path.join(repo, f);
    if (fs.existsSync(p) && fs.statSync(p).isFile()) {
      const text = fs.readFileSync(p, 'utf-8').slice(0, maxCharsPerFile);
      chunks.push(`### ${f}\n\`\`\`\n${text}\n\`\`\``);
    }
  }
  return chunks.slice(0, 8).join('\n\n');
}

/** Hand-rolled SVG line chart — zero dependencies, renders anywhere. */

function svgChart(scores: number[], threshold: number): string {
  const W = 480,
    H = 300,
    pad = 40;
  const n = Math.max(scores.length - 1, 1);
  const x = (i: number) => pad + (i / n) * (W - 2 * pad);
  const y = (s: number) => H - pad - (s / 10) * (H - 2 * pad);
  const pts = scores.map((s, i) => `${x(i)},${y(s)}`).join(' ');
  const dots = scores
    .map((s, i) => `<circle cx="${x(i)}" cy="${y(s)}" r="4" fill="#6366f1"/>`)
    .join('');
  const thY = y(threshold);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" font-family="sans-serif" font-size="12">
  <rect width="${W}" height="${H}" fill="white"/>
  <line x1="${pad}" y1="${H - pad}" x2="${W - pad}" y2="${H - pad}" stroke="#9ca3af"/>
  <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${H - pad}" stroke="#9ca3af"/>
  <line x1="${pad}" y1="${thY}" x2="${W - pad}" y2="${thY}" stroke="#ef4444" stroke-dasharray="4"/>
  <text x="${W - pad}" y="${thY - 4}" text-anchor="end" fill="#ef4444">pass ${threshold}</text>
  <polyline points="${pts}" fill="none" stroke="#6366f1" stroke-width="2"/>
  ${dots}
  <text x="${W / 2}" y="${H - 8}" text-anchor="middle" fill="#374151">Revision</text>
  <text x="14" y="${H / 2}" text-anchor="middle" fill="#374151" transform="rotate(-90 14 ${H / 2})">Score /10</text>
</svg>`;
}

async function handleInteractive(state: ReflexionStateV2): Promise<Answers> {
  const readline = require('readline').createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const question = (query: string): Promise<string> =>
    new Promise((resolve) => readline.question(query, resolve));

  console.log('\n--- INTERACTIVE MODE ---');
  const questions = state.interview?.questions || [];
  const answers: Answers = { runId: state.runId, decisions: [] };

  for (const q of questions) {
    console.log(`\nQuestion: ${q.question}`);
    console.log(`Target: ${q.target} '${q.ref}'`);
    console.log(`Why: ${q.why}`);
    const ans = await question('> ');
    if (ans.trim() === '/approve') {
      answers.directive = 'approve';
      readline.close();
      return answers;
    }
    if (ans.trim() === '/stop') {
      answers.directive = 'stop';
      readline.close();
      return answers;
    }
    answers.decisions.push({ id: q.id, answer: ans.trim() });
  }

  readline.close();
  return answers;
}

async function main(): Promise<number> {
  const resumeArg = arg('--resume');
  const answersArg = arg('--answers');
  const isInteractive = hasFlag('--interactive');
  const autoMode = hasFlag('--auto');

  const repo = arg('--repo') || '.';
  const maxRevisions = Number(arg('--max') || 3);
  const passThreshold = Number(arg('--threshold') || 8);
  const tier = arg('--tier') as Tier | undefined;
  const maxCostUsd = tier === 'local' ? undefined : (arg('--max-cost-usd')
    ? Number(arg('--max-cost-usd'))
    : undefined);
  const maxTokens = arg('--max-tokens')
    ? Number(arg('--max-tokens'))
    : undefined;
  const maxWallClockMs = arg('--max-wallclock-ms')
    ? Number(arg('--max-wallclock-ms'))
    : (tier === 'local' && process.env.REFLEXION_MAX_WALLCLOCK_MS ? Number(process.env.REFLEXION_MAX_WALLCLOCK_MS) : undefined);
  const focus = arg('--focus') ? arg('--focus')!.split(',') : undefined;

  const sizeScore = arg('--size-score') ? Number(arg('--size-score')) : 0;
  const riskSignals = arg('--risk-signals') ? arg('--risk-signals')!.split(',') : [];

  // Let --out default to .reflexion-out unless resuming from a specific dir
  let outDir = arg('--out') || '.reflexion-out';
  let runIdToResume: string | undefined;

  if (resumeArg) {
    if (fs.existsSync(resumeArg) && fs.statSync(resumeArg).isDirectory()) {
      outDir = resumeArg;
    } else {
      runIdToResume = resumeArg;
      // Assume the default outDir if they just passed a runId
    }
  }

  const stateStore = new FileStateStore(outDir);
  const runner = runnerFromEnv();
  console.error(
    `[reflexion] creator=${runner.models.creator} critic=${runner.models.critic}`
  );

  let result: ReflexionResult;

  if (resumeArg) {
    const state = await stateStore.load(runIdToResume || 'default');
    if (!state) {
      console.error(`[reflexion] No state found in ${outDir} to resume.`);
      return 1;
    }

    let answers: Answers;

    if (isInteractive) {
      answers = await handleInteractive(state);
    } else if (answersArg) {
      const answersText =
        answersArg === '-'
          ? fs.readFileSync(0, 'utf-8')

        : fs.readFileSync(answersArg, 'utf-8');
    answers = parseYamlAnswers(answersText);
  } else {
    console.error(
      '[reflexion] --resume requires --answers <file|-> or --interactive.'
    );
    return 1;
  }

  result = await resumeReflexion(
    runner,
    state,
    answers,
    {
      brief: state.brief,
      stack: readStack(repo),
      maxRevisions: state.params.maxRevisions,
      passThreshold: state.params.passThreshold,
      budget: { maxCostUsd, maxTotalTokens: maxTokens, maxWallClockMs },
      focusPillars: focus,
      stateStore,
    },
    (e) => {
      if (e.phase === 'scored' && e.critique) {
        const c = e.critique;
        console.error(
          `[reflexion] rev ${e.revision}: ${c.score}/10 ` +
            `[gstack ${c.gstackDiagnosis} | atomic ${c.atomicBatches} | ethos ${c.productionEthos} | web ${c.modernWeb}] passed=${c.passed}`
        );
      } else {
        console.error(`[reflexion] phase: ${e.phase}`);
      }
    }
  );
} else {
  const briefFile = arg('--brief-file');
  const fileArg = arg('--file');

  let positional: string | undefined;
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith('--')) {
      const flag = args[i];
      if (
        [
          '--brief-file',
          '--file',
          '--repo',
          '--max',
          '--threshold',
          '--max-cost-usd',
          '--max-tokens',
          '--max-wallclock-ms',
          '--focus',
          '--out',
          '--resume',
          '--answers',
          '--tier',
          '--size-score',
          '--risk-signals',

      ].includes(flag)
    ) {
      i++; // skip its value
    }
  } else {
    positional = args[i];
    break;
  }
}

let brief: string | undefined;
if (fileArg) {
  brief = fs.readFileSync(fileArg, 'utf-8'); // read verbatim
} else if (briefFile) {
  brief = fs.readFileSync(briefFile, 'utf-8').trim();
} else {
  brief = positional?.trim();
}

if (!brief) {
  console.error(
    'Usage: reflexion-loop "<brief>" [--file <path>] [--repo .] [--max 3] [--threshold 8] [--out .reflexion-out]'
  );
  return 1;
}

if (tier && tier !== 'byo') {
  const assessment = assessTask({ sizeScore, riskSignals });
  const enforcement = enforceTier(tier, assessment);
  if (!enforcement.allowed) {
    console.error(`[reflexion] REFUSED by tier policy (${tier}): ${enforcement.reason}`);
    if (enforcement.escalateTo) {
      console.error(`[reflexion] -> Escalate to ${enforcement.escalateTo}`);
    }
    return 1; // Or another exit code? 1 is fine for error
  }
}

result = await runReflexion(
  runner,
  {
    brief,
    stack: readStack(repo),
    maxRevisions,
    passThreshold,
    mode: autoMode ? 'auto' : 'interview',
    budget: { maxCostUsd, maxTotalTokens: maxTokens, maxWallClockMs },
    focusPillars: focus,
    stateStore,
  },
  (e) => {
    if (e.phase === 'scored' && e.critique) {
      const c = e.critique;
      console.error(
        `[reflexion] rev ${e.revision}: ${c.score}/10 ` +
          `[gstack ${c.gstackDiagnosis} | atomic ${c.atomicBatches} | ethos ${c.productionEthos} | web ${c.modernWeb}] passed=${c.passed}`
      );
    } else {
      console.error(`[reflexion] phase: ${e.phase}`);
    }

    }
  );
}

// Determine exit code BEFORE writing artifacts
let exitCode = 0;
if (result.stopReason === 'passed' || result.stopReason === 'user-approve') {
  exitCode = 0;
} else if (
  !result.stopReason &&
  result.interview &&
  result.interview.questions.length > 0
) {
  exitCode = 2; // parked
} else if (
  result.stopReason === 'budget-exceeded' ||
  result.stopReason === 'user-stop' ||
  result.stopReason === 'wallclock-exceeded'
) {
  exitCode = 3;
} else if (
  result.stopReason === 'refine-contract-violation' ||
  result.verdict === 'unknown'
) {
  exitCode = 4;
} else {
  // If auto mode hits max-revisions, it doesn't pass. Could be considered exit 2 per v1, or 2 per v2 specs.
  // The spec says "2 phase 'AWAITING_ANSWERS' (parked)".
  // So max-revisions in auto mode should be 2 for failure to pass? Or 2 because it's not passed?
  // Let's stick to v1: exit 2 if hit revision cap without passing.
  exitCode = 2;
}

// Ensure output directory exists (state store saves it but just in case)
fs.mkdirSync(outDir, { recursive: true });

if (result.rounds.length > 0) {
  fs.writeFileSync(
    path.join(outDir, 'plan.md'),
    result.rounds.at(-1)?.draft ?? ''
  );
  fs.writeFileSync(
    path.join(outDir, 'critique.json'),
    JSON.stringify(result, null, 2)
  );
  if (result.scores.length >= 2) {
    fs.writeFileSync(
      path.join(outDir, 'diminishing-returns.svg'),
      svgChart(result.scores, passThreshold)
    );
  }
}

if (
  exitCode === 2 &&
  result.interview &&
  result.interview.questions.length > 0
) {
  fs.writeFileSync(
    path.join(outDir, 'interview.md'),

      formatInterviewMd(result.runId, result.interview.questions)
    );
  } else if (exitCode === 0) {
    fs.writeFileSync(path.join(outDir, 'ide-prompt.md'), result.idePrompt);
  }

  console.log('\n' + '='.repeat(56));
  if (result.criticDegraded) {
    console.log(
      '⚠️  WARNING: Critique ran in fallback mode (Gemini 3.1 Pro) because the Claude API was unavailable — model separation was reduced; review this plan with extra scrutiny.'
    );
    console.log('-'.repeat(56));
  }
  console.log(`Scores per revision : ${JSON.stringify(result.scores)}`);
  console.log(
    `Final score         : ${result.finalScore}/10  passed=${result.finalPassed}`
  );
  console.log(`Revisions used      : ${result.revisionsUsed}/${maxRevisions}`);
  console.log('-'.repeat(56));
  console.log('ADJUDICATOR VERDICT:\n' + result.verdict);
  console.log('-'.repeat(56));
  console.log(`Artifacts written to: ${path.resolve(outDir)}`);
