      (c) =>
        c.command === 'git' ||
        (typeof c.fullCommand === 'string' && c.fullCommand.includes('git'))
    );

    for (const gitCall of gitCalls) {
      const subCommand =
        gitCall.args[0] || (gitCall.fullCommand.split(' ')[1] ?? '');
      if (subCommand) {
        expect([
          'status',
          'diff',
          'log',
          'rev-parse',
          'ls-files',
          'show',
        ]).toContain(subCommand);
      }
    }
  });
});

