export interface ModelCapabilities {
  supportsStructuredOutput: boolean;
  supportsToolCalling: boolean;
  supportsPromptCache: boolean;
}

const CAPABILITIES_BY_ID: Record<string, Partial<ModelCapabilities>> = {
  // specific models that might lack capabilities e.g. o1-preview
  'o1-preview': {
    supportsStructuredOutput: false,
    supportsToolCalling: false,
    supportsPromptCache: false,
  },
  'o1-mini': {
    supportsStructuredOutput: false,
    supportsToolCalling: false,
    supportsPromptCache: false,
  }
};

const CAPABILITIES_BY_FAMILY: Record<string, Partial<ModelCapabilities>> = {
  'anthropic': {
    supportsStructuredOutput: true,
    supportsToolCalling: true,
    supportsPromptCache: true,
  },
  'google': {
    supportsStructuredOutput: true,
    supportsToolCalling: true,
    supportsPromptCache: true,
  },
  'openai': {
    supportsStructuredOutput: true,
    supportsToolCalling: true,
    supportsPromptCache: false,
  }
};

/**
 * Returns the capabilities of a given model ID.
 * Falls back to family-level capabilities if the specific ID is not listed.
 */

export function getModelCapabilities(modelId: string): ModelCapabilities {
  const family = providerOf(modelId);
  const familyCaps = CAPABILITIES_BY_FAMILY[family] || {};
  const idCaps = CAPABILITIES_BY_ID[modelId] || {};

  return {
    supportsStructuredOutput: true, // safe default
    supportsToolCalling: true,
    supportsPromptCache: false,
    ...familyCaps,
    ...idCaps,
  };
}

/**
 * Guards against routing an incapable model to a structural critic role.
 * Throws a clear configuration error if the model cannot reliably produce structured output.
 */

export function assertCanCritique(modelId: string): void {
  const caps = getModelCapabilities(modelId);
  if (!caps.supportsStructuredOutput) {
    throw new Error(`Configuration Error: Model "${modelId}" cannot be used as a critic because it lacks reliable structured output support.`);
  }
}

export type ProviderFamily = 'anthropic' | 'google' | 'openai' | 'local';

/**
 * Prefix rules, evaluated top-to-bottom. Add rows here when you onboard a new
 * model family. Jules models are Gemini variants → they resolve to 'google'
 * (the *key* used for them is chosen by the resolver, not by this table).
 */

const PREFIX_RULES: Array<[RegExp, ProviderFamily]> = [
  [/^claude/i, 'anthropic'],
  [/^(gemini|jules|models\/gemini)/i, 'google'],
  [/^(gpt|o[1-9]|chatgpt|text-|omni)/i, 'openai'],
];

export function providerOf(modelId: string): ProviderFamily {
  const id = (modelId ?? '').trim();
  if (process.env.LOCAL_MODEL_ENDPOINT && id === process.env.LOCAL_MODEL_NAME) {
    return 'local';
  }
  for (const [re, family] of PREFIX_RULES) {
    if (re.test(id)) return family;
  }
  throw new Error(
    `model-registry: cannot infer a provider for model id "${modelId}". ` +
      `Add a rule to PREFIX_RULES or pass an explicit family.`
  );
}

/**
 * Build a LanguageModel for `modelId` using the supplied key. The SDK is chosen
 * purely from the model id, so any responsibility can be pointed at any model.
 */

export function createModel(modelId: string, apiKey: string): LanguageModel {
  if (providerOf(modelId) === 'local') {
    return createOpenAI({ baseURL: process.env.LOCAL_MODEL_ENDPOINT, apiKey: apiKey || 'local' })(modelId);
  }
  if (!apiKey?.trim()) {
    throw new Error(
      `model-registry: no API key supplied for model "${modelId}".`
    );
  }
  const key = apiKey.trim();
  switch (providerOf(modelId)) {
    case 'anthropic':
      return createAnthropic({ apiKey: key })(modelId);
    case 'google':
      return createGoogleGenerativeAI({ apiKey: key })(modelId);
    case 'openai':
      return createOpenAI({ apiKey: key })(modelId);
    case 'local':
      return createOpenAI({ baseURL: process.env.LOCAL_MODEL_ENDPOINT, apiKey: key || 'local' })(modelId);
  }
}

