const TASK_SIZE_WEIGHTS: Record<TaskSize, number> = {
  XS: 0,
  S: 1,
  M: 2,
  L: 3,
  XL: 4,
};

export interface TaskAssessment {
  size: TaskSize;
  risk: RiskLevel;
}

export function assessTask(input: { sizeScore: number; riskSignals: string[] }): TaskAssessment {
  // Score -> Size Mapping: 0-1->XS, 2-3->S, 4-5->M, 6-8->L, 9+->XL
  let size: TaskSize = 'XL';
  if (input.sizeScore <= 1) size = 'XS';
  else if (input.sizeScore <= 3) size = 'S';
  else if (input.sizeScore <= 5) size = 'M';
  else if (input.sizeScore <= 8) size = 'L';

  // Risk Mapping
  let risk: RiskLevel = 0;
  const risk2Pattern = /auth|payment|billing|secret|token|migration|infra|database|schema|prod/i;

  if (input.riskSignals.some((signal) => risk2Pattern.test(signal))) {
    risk = 2;
  } else if (input.riskSignals.length > 0) {
    risk = 1;
  }

  return { size, risk };
}

export interface TierEnforcementResult {
  allowed: boolean;
  reason?: string;
  escalateTo?: Tier;
}

export function enforceTier(tier: Tier, assessment: TaskAssessment): TierEnforcementResult {
  const policy = TIER_POLICY[tier];

  const assessmentSizeWeight = TASK_SIZE_WEIGHTS[assessment.size];
  const policySizeWeight = TASK_SIZE_WEIGHTS[policy.maxTaskSize];

  if (assessmentSizeWeight > policySizeWeight) {
    return {
      allowed: false,
      reason: `Task size ${assessment.size} exceeds tier maximum of ${policy.maxTaskSize}.`,
      escalateTo: policy.escalateTo ?? undefined,
    };
  }

  if (assessment.risk > policy.maxRiskLevel) {
    return {
      allowed: false,
      reason: `Task risk level ${assessment.risk} exceeds tier maximum of ${policy.maxRiskLevel}.`,
      escalateTo: policy.escalateTo ?? undefined,
    };
  }

  return { allowed: true };
}

export function deriveLoopParams(tier: Tier): { maxRevisions: number; maxLanes: number; autoEscalate: boolean } {
  const policy = TIER_POLICY[tier];
  return {
    maxRevisions: policy.maxCritiquePasses,
    maxLanes: policy.maxLanes,
    autoEscalate: tier === 'sub-max',
  };
}

import { encrypt, decrypt } from './crypto';

describe('crypto', () => {
  const originalEnv = process.env;
  const validKey =
    '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';

  beforeEach(() => {
    jest.resetModules();
    process.env = { ...originalEnv };
  });

  afterAll(() => {
    process.env = originalEnv;
  });

  describe('encrypt and decrypt', () => {
    it('should successfully encrypt and decrypt a string with a valid key', () => {
      process.env.ENCRYPTION_KEY = validKey;
      const plaintext = 'This is a secret message!';

      const ciphertext = encrypt(plaintext);
      expect(typeof ciphertext).toBe('string');
      expect(ciphertext).not.toBe(plaintext);
      expect(ciphertext.split(':').length).toBe(3);

      const decrypted = decrypt(ciphertext);
      expect(decrypted).toBe(plaintext);
    });

    it('should successfully encrypt and decrypt empty strings', () => {
      process.env.ENCRYPTION_KEY = validKey;
      const plaintext = '';

      const ciphertext = encrypt(plaintext);
      const decrypted = decrypt(ciphertext);
      expect(decrypted).toBe(plaintext);
    });
  });

  describe('ENCRYPTION_KEY validation', () => {
    it('should throw an error if ENCRYPTION_KEY is not set', () => {
      delete process.env.ENCRYPTION_KEY;
      expect(() => encrypt('test')).toThrow(
        'ENCRYPTION_KEY environment variable is not set'
      );
      expect(() => decrypt('part1:part2:part3')).toThrow(
        'ENCRYPTION_KEY environment variable is not set'
      );
    });

    it('should throw an error if ENCRYPTION_KEY is not 64 characters', () => {
      process.env.ENCRYPTION_KEY = 'short';
      expect(() => encrypt('test')).toThrow(
        'ENCRYPTION_KEY must be exactly 64 hex characters (32 bytes)'
      );
      expect(() => decrypt('part1:part2:part3')).toThrow(
        'ENCRYPTION_KEY must be exactly 64 hex characters (32 bytes)'
      );
    });

  });

  describe('decrypt error handling', () => {
    let consoleSpy: jest.SpyInstance;

    beforeEach(() => {
      process.env.ENCRYPTION_KEY = validKey;
      consoleSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    });

    afterEach(() => {
      consoleSpy.mockRestore();
    });

    it('should throw an error if ciphertext format is invalid', () => {
      expect(() => decrypt('invalid_format')).toThrow(
        'Invalid ciphertext format. Expected <iv>:<ciphertext>:<authtag>'
      );
      expect(() => decrypt('part1:part2')).toThrow(
        'Invalid ciphertext format. Expected <iv>:<ciphertext>:<authtag>'
      );
      expect(() => decrypt('part1:part2:part3:part4')).toThrow(
        'Invalid ciphertext format. Expected <iv>:<ciphertext>:<authtag>'
      );
    });

    it('should fail to decrypt if ciphertext is tampered with', () => {
      const plaintext = 'Secret data';
      const ciphertext = encrypt(plaintext);

      const parts = ciphertext.split(':');
      // Modify the ciphertext part significantly to ensure it changes
      parts[1] =
        parts[1] === '0000000000000000000000'
          ? '1111111111111111111111'
          : '0000000000000000000000';
      const tamperedCiphertext = parts.join(':');

      expect(() => decrypt(tamperedCiphertext)).toThrow(); // Decipher throws when auth tag fails
    });

    it('should fail to decrypt if auth tag is tampered with', () => {
      const plaintext = 'Secret data';
      const ciphertext = encrypt(plaintext);

      const parts = ciphertext.split(':');
      // Modify the auth tag
      parts[2] = '00000000000000000000000000000000';
      const tamperedAuthTag = parts.join(':');

      expect(() => decrypt(tamperedAuthTag)).toThrow(); // Decipher throws when auth tag fails
    });
  });
});

import * as crypto from 'crypto';

/**
 * AES-256-GCM encryption key derived from environment variables.
 * Needs to be 32 bytes (64 hex characters).
 */

function getEncryptionKey(): Buffer {
  const hexKey = process.env.ENCRYPTION_KEY;
  if (!hexKey) {
    throw new Error('ENCRYPTION_KEY environment variable is not set');
  }
  if (hexKey.length !== 64) {
    throw new Error('ENCRYPTION_KEY must be exactly 64 hex characters (32 bytes)');
  }
  return Buffer.from(hexKey, 'hex');
}

/**
 * @desc Encrypts plaintext using AES-256-GCM.
 *       Reads key from process.env.ENCRYPTION_KEY (64 hex chars = 32 bytes).
 * @param plaintext - The value to encrypt
 * @returns Self-contained encrypted string: "<iv>:<ciphertext>:<authtag>"
 */

export function encrypt(plaintext: string): string {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12); // GCM standard IV size
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag().toString('hex');

  return `${iv.toString('hex')}:${encrypted}:${authTag}`;
}

/**
 * @desc Decrypts a value produced by encrypt().
 * @param ciphertext - The "<iv>:<ciphertext>:<authtag>" string from DB
 * @returns Original plaintext
 */

export function decrypt(ciphertext: string): string {
  if (!ciphertext || !ciphertext.includes(':')) {
    throw new Error('Invalid ciphertext format. Expected <iv>:<ciphertext>:<authtag>. It seems the value is not encrypted.');
  }

  const key = getEncryptionKey();
  const parts = ciphertext.split(':');

  if (parts.length !== 3) {
    throw new Error('Invalid ciphertext format. Expected <iv>:<ciphertext>:<authtag>');
  }

  const [ivHex, encryptedHex, authTagHex] = parts;

  const iv = Buffer.from(ivHex, 'hex');
  const authTag = Buffer.from(authTagHex, 'hex');

  try {
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  } catch (err) {
    console.error('Decryption failed:', err);
    throw new Error('Decryption failed. This usually means the ENCRYPTION_KEY has changed or the data is corrupted.');
  }
}

