import { telemetryService } from '../lib/telemetry-service';
import {
  isSkillTrace,
  normalizeProjectName,
  normalizeSkillName,
} from '../lib/trace-utils';
import { UserResolver } from './user-resolver';

export interface ITelemetry {
  withAnalytics<T>(
    skillName: string,
    projectName: string | undefined,
    model: string | undefined,
    agent: string | undefined,
    skillCost: string | undefined,
    executeCallback: () => Promise<T>,
    overrides?: {
      userEmail?: string;
      userRole?: string;
      actorType?: string | null;
      autonomy?: string | null;
      loopRunId?: string | null;
      loopPhase?: string | null;
      teamRole?: string | null;
    }
  ): Promise<T>;
}

/**
 * Telemetry orchestration for MCP server.
 * Delegates actual recording to the unified TelemetryService.
 */

export class Telemetry implements ITelemetry {
  private userResolver: UserResolver;

  constructor() {
    this.userResolver = new UserResolver();
  }

  async withAnalytics<T>(
    skillName: string,
    projectName: string | undefined,
    model: string | undefined,
    agent: string | undefined,
    skillCost: string | undefined,
    executeCallback: () => Promise<T>,
    overrides?: {
      userEmail?: string;
      userRole?: string;
      actorType?: string | null;
      autonomy?: string | null;
      loopRunId?: string | null;
      loopPhase?: string | null;
      teamRole?: string | null;
    }
  ): Promise<T> {
    const normalizedSkill = normalizeSkillName(skillName);
    const startTime = Date.now();

    // Skip internal/system traces
    if (isSkillTrace(undefined, normalizedSkill)) {
      return executeCallback();
    }

    const userEmail = overrides?.userEmail || this.userResolver.getUserEmail();
    const userName = this.userResolver.getUserName();
    const normalizedProject = normalizeProjectName(projectName);

    let status: 'SUCCESS' | 'ERROR' = 'SUCCESS';
    let errorMessage: string | undefined;
    let completionTokens = 0;
    let promptTokens = 500; // Baseline for MCP metadata

    try {
      const result = await executeCallback();
      const outputStr =
        typeof result === 'string' ? result : JSON.stringify(result);
      completionTokens = Math.ceil(outputStr.length / 4);
      return result;
    } catch (error: unknown) {
      status = 'ERROR';
      errorMessage = error instanceof Error ? error.message : String(error);
      throw error;
    } finally {
      const duration = (Date.now() - startTime) / 1000;

      try {
        if (telemetryService?.recordEvent) {
          await telemetryService.recordEvent({
            skillName,
            projectName: normalizedProject,
            model,

            agent,
            duration,
            status,
            error: errorMessage,
            promptTokens,
            completionTokens,
            userEmail,
            metadata: {
              userName,
              skillCost: skillCost || 'unknown',
              source: 'mcp',
            },
            actorType: overrides?.actorType !== undefined ? overrides.actorType : 'AGENT',
            autonomy: overrides?.autonomy !== undefined ? overrides.autonomy : 'DIRECTED',
            loopRunId: overrides?.loopRunId,
            loopPhase: overrides?.loopPhase,
            teamRole: overrides?.teamRole,
          });
        } else {
          console.error(
            '[MCP Telemetry] telemetryService unavailable - skipping recording.'
          );
        }
      } catch (logError) {
        console.error(
          '[MCP Telemetry] Failed to delegate recording:',
          logError
        );
      }
    }
  }
}

import { execSync } from "child_process";

/**
 * UserResolver extracts identity information from the environment.
 * Enforces SRP by isolating identity resolution from telemetry orchestration.
 */

export class UserResolver {
  /**
   * Strictly gets user email from GitHub CLI for dashboard parity, with fallbacks to git config.
   */
  getUserEmail(): string {
    let userEmail = 'unknown';
    try {
      // Primary: GitHub CLI (best for parity with GitHub OAuth)
      userEmail = execSync('gh api user -q .email', { stdio: 'pipe' })
        .toString()
        .trim();

      // If GH CLI returns nothing or empty, fallback to git config
      if (!userEmail || userEmail === 'null') {
         userEmail = execSync('git config --global user.email', { stdio: 'pipe' })
           .toString()
           .trim();
      }
    } catch {
      try {
        // Fallback: Git Config
        userEmail = execSync('git config --global user.email', { stdio: 'pipe' })
          .toString()
          .trim();
      } catch {
        // Fallback: Env variable
        userEmail = process.env.USER_EMAIL || 'unknown';
      }
    }
    return userEmail;
  }

  /**
   * Retrieves user name from git configuration.
   */
  getUserName(): string {
    try {
      return execSync('git config --global user.name', { stdio: 'pipe' })
        .toString()
        .trim();
    } catch {
      return 'unknown';
    }
  }
}

