import fs from 'node:fs/promises';
import path from 'node:path';

async function testSearch() {
  const query = "planning-expert";

  const response = await fetch('http://localhost:11434/api/embeddings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'nomic-embed-text', prompt: query })
  });
  const { embedding: queryEmbedding } = await response.json();

  const indexPath = path.join(process.cwd(), '.tls-index', 'index.json');
  const index = JSON.parse(await fs.readFile(indexPath, 'utf8'));

  const similarity = (a, b) => {
    let dot = 0, normA = 0, normB = 0;
    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }
    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
  };

  const results = index.chunks.map(chunk => ({
    ...chunk,
    score: chunk.embedding ? similarity(queryEmbedding, chunk.embedding) : -1
  })).sort((a, b) => b.score - a.score).slice(0, 1);

  console.log(`Top result file: ${results[0].path}`);
  console.log(`Top result lines: ${results[0].startLine}-${results[0].endLine}`);
  console.log(`Score: ${results[0].score}`);
  console.log(`Length in characters: ${results[0].text.length}`);
}

testSearch();
